        return { metaKey: route.path }
      }
    }
  })

  fastify.get('/test', () => {})
  fastify.get('/test/hello', () => {})
  fastify.get('/testing', () => {})
  fastify.get('/testing/:param', () => {})
  fastify.put('/update', () => {})

  await fastify.ready()

  const result = fastify.printRoutes({ includeMeta: true })
  const expected = `\
└── /
    ├── test (GET, HEAD)
    │   • (metaKey) "/test"
    │   ├── /hello (GET, HEAD)
    │   │   • (metaKey) "/test/hello"
    │   └── ing (GET, HEAD)
    │       • (metaKey) "/testing"
    │       └── /
    │           └── :param (GET, HEAD)
    │               • (metaKey) "/testing/:param"
    └── update (PUT)
        • (metaKey) "/update"
`

  t.assert.strictEqual(result, expected)
})

